#!/usr/bin/env node
/** Dev orchestration: Vite (renderer) + tsup watch (main/preload/host) + Electron. */

import { spawn } from "node:child_process";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { resolveElectronBinary, resolvePackageFile, terminateProcessTree } from "./process-utils.mjs";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const rendererUrl = "http://localhost:5173";

export async function waitForViteReady(url, options = {}) {
  const fetchImpl = options.fetch ?? globalThis.fetch;
  const now = options.now ?? Date.now;
  const sleep = options.sleep ?? ((delay) => new Promise((resolve) => setTimeout(resolve, delay)));
  const timeoutMs = options.timeoutMs ?? 30_000;
  const intervalMs = options.intervalMs ?? 100;
  const deadline = now() + timeoutMs;
  let lastFailure = "no response";

  while (now() < deadline) {
    try {
      const remaining = Math.max(1, deadline - now());
      const response = await fetchImpl(url, { signal: globalThis.AbortSignal.timeout(Math.min(1_000, remaining)) });
      if (response.ok) return;
      lastFailure = `HTTP ${response.status}`;
    } catch (error) {
      lastFailure = error instanceof Error ? error.message : String(error);
    }
    await sleep(Math.min(intervalMs, Math.max(0, deadline - now())));
  }
  throw new Error(`Vite did not become ready at ${url} within ${timeoutMs}ms (last failure: ${lastFailure})`);
}

export function createDevRuntime(projectRoot = root) {
  const children = new Set();
  let shuttingDown = false;

  const shutdown = (code = 0) => {
    if (shuttingDown) return;
    shuttingDown = true;
    for (const child of children) terminateProcessTree(child);
    process.exit(code);
  };

  const run = (label, command, args, options = {}) => {
    const child = spawn(command, args, {
      cwd: projectRoot,
      stdio: "inherit",
      detached: process.platform !== "win32",
      env: { ...process.env, ...options.env },
    });
    children.add(child);
    child.once("error", (error) => {
      children.delete(child);
      if (!shuttingDown && options.fatal !== false) {
        console.error(`[dev] ${label} failed to start: ${error.message}`);
        shutdown(1);
      }
    });
    child.once("exit", (code, signal) => {
      children.delete(child);
      if (!shuttingDown && options.fatal !== false) {
        console.error(`[dev] ${label} exited code=${code ?? "none"} signal=${signal ?? "none"}`);
        const exitCode = code === 0 ? (options.allowCleanExit ? 0 : 1) : (code ?? 1);
        shutdown(exitCode);
      }
    });
    return child;
  };

  return { children, run, shutdown };
}

async function waitForSuccessfulBuild(child) {
  const result = await new Promise((resolve) => {
    child.once("error", (error) => resolve({ error }));
    child.once("exit", (code, signal) => resolve({ code, signal }));
  });
  if (result.error) throw new Error(`initial build failed to start: ${result.error.message}`);
  if (result.signal) throw new Error(`initial build terminated by signal ${result.signal}`);
  if (result.code !== 0) throw new Error(`initial build exited with status ${result.code ?? "none"}`);
}

export async function runDev(projectRoot = root) {
  const runtime = createDevRuntime(projectRoot);
  process.once("SIGINT", () => runtime.shutdown(0));
  process.once("SIGTERM", () => runtime.shutdown(0));

  console.log("[dev] building main/preload/host…");
  const initialBuild = runtime.run("initial build", process.execPath, ["scripts/build-main.mjs"], { fatal: false });
  try {
    await waitForSuccessfulBuild(initialBuild);
    const tsupCli = resolvePackageFile(projectRoot, "tsup", "dist/cli-default.js");
    const viteCli = resolvePackageFile(projectRoot, "vite", "bin/vite.js");
    runtime.run("tsup watch", process.execPath, [tsupCli, "--config", "tsup.config.ts", "--watch"]);
    runtime.run("Vite", process.execPath, [viteCli, "--config", "vite.config.ts"]);
    await waitForViteReady(rendererUrl);

    console.log("[dev] Vite ready; starting Electron…");
    runtime.run("Electron", resolveElectronBinary(projectRoot), ["."], {
      allowCleanExit: true,
      env: {
        VITE_DEV_SERVER_URL: rendererUrl,
        ELECTRON_DISABLE_SECURITY_WARNINGS: "1",
      },
    });
  } catch (error) {
    console.error(`[dev] ${error instanceof Error ? error.message : error}`);
    runtime.shutdown(1);
  }
}

const isMain = process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href;
if (isMain) void runDev();

export const TOOL_CAPABILITY_IDS = [
  "shell.bash",
  "shell.powershell",
  "vcs.git",
  "js.node",
  "js.npm",
  "js.npx",
  "js.bun",
  "python.interpreter",
  "python.uv",
  "python.uvx",
  "search.rg",
  "search.fd",
  "data.jq",
  "network.curl",
] as const;

export type ToolCapabilityId = (typeof TOOL_CAPABILITY_IDS)[number];

export const MANAGED_COMPONENT_IDS = [
  "portable-git",
  "node-lts",
  "cpython",
  "uv",
  "ripgrep",
  "fd",
  "jq",
  "bun",
] as const;

export type ManagedComponentId = (typeof MANAGED_COMPONENT_IDS)[number];

export const TOOLCHAIN_PROFILE_IDS = [
  "javascript-essentials",
  "python-essentials",
  "windows-shell-essentials",
  "cli-essentials",
] as const;

export type ToolchainProfileId = (typeof TOOLCHAIN_PROFILE_IDS)[number];

export const TOOLCHAIN_CACHE_IDS = ["npm", "uv", "bun", "downloads"] as const;

export type ToolchainCacheId = (typeof TOOLCHAIN_CACHE_IDS)[number];

export const TOOL_PROVIDERS = ["project", "custom", "system", "bundled", "managed", "legacy-upstream-managed"] as const;

export type ToolProvider = (typeof TOOL_PROVIDERS)[number];

export const TOOL_PREFERENCES = ["auto", "system", "bundled", "managed", "custom"] as const;

export type ToolPreference = (typeof TOOL_PREFERENCES)[number];

export const TOOL_HEALTH_VALUES = [
  "healthy",
  "missing",
  "incomplete",
  "unsupported",
  "unverified",
  "broken",
  "modified",
  "blocked-by-trust",
] as const;

export type ToolHealth = (typeof TOOL_HEALTH_VALUES)[number];

export const TOOLCHAIN_ERROR_CODES = [
  "TOOLCHAIN_CAPABILITY_REQUIRED",
  "TOOLCHAIN_NODE_REQUIRED",
  "TOOLCHAIN_PYTHON_REQUIRED",
  "TOOLCHAIN_GIT_REQUIRED",
  "TOOLCHAIN_BASH_REQUIRED",
  "TOOLCHAIN_UV_REQUIRED",
  "TOOLCHAIN_INCOMPLETE",
  "TOOLCHAIN_UNSUPPORTED",
  "TOOLCHAIN_UNVERIFIED",
  "TOOLCHAIN_BROKEN",
  "TOOLCHAIN_MODIFIED",
  "TOOLCHAIN_PROJECT_UNTRUSTED",
  "TOOLCHAIN_DOWNLOAD_OFFLINE",
  "TOOLCHAIN_DOWNLOAD_REJECTED",
  "TOOLCHAIN_INTEGRITY_FAILED",
  "TOOLCHAIN_EXTRACTION_FAILED",
  "TOOLCHAIN_INSTALL_BUSY",
  "TOOLCHAIN_PERMISSION_DENIED",
  "TOOLCHAIN_INVALID_SELECTION",
  "TOOLCHAIN_INVALID_CATALOG",
  "TOOLCHAIN_CANCELLED",
  "TOOLCHAIN_INTERNAL",
] as const;

export type ToolchainErrorCode = (typeof TOOLCHAIN_ERROR_CODES)[number];

export interface ToolCandidate {
  id: string;
  capability: ToolCapabilityId;
  provider: ToolProvider;
  discovery: string;
  executable: string;
  argvPrefix?: string[];
  binDir: string;
  version?: string;
  componentId?: ManagedComponentId;
  componentRoot?: string;
  health: ToolHealth;
  reasonCode?: ToolchainErrorCode;
  rank: number;
  pathOrder?: number;
  discoveredAt?: string;
}

export interface CommandDescriptor {
  capability: ToolCapabilityId;
  provider: ToolProvider;
  executable: string;
  argvPrefix: string[];
  binDir: string;
  /** Additional context-only PATH entries, ordered before binDir. */
